def attribute_queued_participant_messages(apps, schema_editor):
    """Attach old optional messages to their source camp or fail them closed."""
    PushMessage = apps.get_model("billing", "PushMessage")
    Camp = apps.get_model("billing", "Camp")
    database = schema_editor.connection.alias
    for message in PushMessage.objects.using(database).filter(category__in=PARTICIPANT_FEATURES):
        camp_id = None
        if message.category == "announcement":
            parts = message.dedupe_key.split(":")
            if len(parts) == 4 and parts[0] == "info" and parts[1].isdigit():
                camp_id = int(parts[1])
        else:
            subscription = message.subscription
            if subscription.participant_id:
                camp_id = subscription.participant.camp_id
            elif subscription.family_member_id:
                camp_id = subscription.family_member.guardian.camp_id
        if camp_id is not None and Camp.objects.using(database).filter(pk=camp_id).exists():
            message.camp_id = camp_id
            message.feature_id = PARTICIPANT_FEATURES[message.category]
            message.save(update_fields=["camp", "feature_id"], using=database)
        elif message.status in {"pending", "processing"}:
            message.status = "failed"
            message.last_error_code = "feature_unattributed"
            message.processing_started_at = None
            message.attempts += 1
            message.save(
                update_fields=["status", "last_error_code", "processing_started_at", "attempts"],
                using=database,
            )


